import "./toast.css";

export interface ToastProps {
  tipo?: "Erro" | "Sucesso";
  faixa?: "Clara" | "Escura";
}

export function Toast({
  tipo = "Erro",
  faixa = "Clara",
}: ToastProps) {
  return (
    <div className="toast" data-tipo={tipo} data-faixa={faixa}>
      <div className="icone">
        <p className="glifo">!</p>
      </div>
      <div className="texto">
        <p className="titulo">Mensagem não enviada</p>
        <p className="mensagem">Erro de conexão. Tente de novo em instantes.</p>
      </div>
      <p className="fechar">×</p>
    </div>
  );
}

/* toast.css */
.toast {
  position: relative;
  width: 360px;
  display: flex;
  flex-direction: row;
  gap: 12px;
  padding: 16px 16px 16px 16px;
  justify-content: flex-start;
  align-items: flex-start;
  border-radius: 12px;
  background: #ECEAE4;
  border: 1px solid #666181;
  box-shadow: 0px 20px 40px -20px rgba(35, 35, 35, 0.35);
}
.icone {
  width: 20px;
  height: 20px;
  display: flex;
  flex-direction: row;
  gap: 0px;
  padding: 0px 0px 0px 0px;
  justify-content: center;
  align-items: center;
  border-radius: 999px;
  background: #8A2606;
}
.glifo {
  color: #F5F3EE;
  font-family: "JetBrains Mono";
  font-size: 13px;
  font-weight: 700;
}
.texto {
  flex: 1 1 0;
  width: 272px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0px 0px 0px 0px;
  justify-content: flex-start;
  align-items: flex-start;
}
.titulo {
  color: #232323;
  font-family: "Inter";
  font-size: 16px;
  font-weight: 600;
}
.mensagem {
  width: 250px;
  color: #45403C;
  font-family: "Inter";
  font-size: 14px;
  font-weight: 400;
}
.fechar {
  color: #564370;
  font-family: "JetBrains Mono";
  font-size: 16px;
  font-weight: 400;
}
.toast[data-tipo="Sucesso"][data-faixa="Clara"] .icone {
  background: #0B5430;
}
.toast[data-tipo="Erro"][data-faixa="Escura"] {
  background: #1A1540;
  border: 1px solid #645D9D;
  box-shadow: 0px 20px 40px -20px rgba(0, 0, 0, 0.60);
}
.toast[data-tipo="Erro"][data-faixa="Escura"] .icone {
  background: #FF9E80;
}
.toast[data-tipo="Erro"][data-faixa="Escura"] .glifo {
  color: #110D2A;
}
.toast[data-tipo="Erro"][data-faixa="Escura"] .titulo {
  color: #E8E4DC;
}
.toast[data-tipo="Erro"][data-faixa="Escura"] .mensagem {
  color: #C9CFE2;
}
.toast[data-tipo="Erro"][data-faixa="Escura"] .fechar {
  color: #82ADC3;
}
.toast[data-tipo="Sucesso"][data-faixa="Escura"] {
  background: #1A1540;
  border: 1px solid #645D9D;
  box-shadow: 0px 20px 40px -20px rgba(0, 0, 0, 0.60);
}
.toast[data-tipo="Sucesso"][data-faixa="Escura"] .icone {
  background: #7BE0A5;
}
.toast[data-tipo="Sucesso"][data-faixa="Escura"] .glifo {
  color: #110D2A;
}
.toast[data-tipo="Sucesso"][data-faixa="Escura"] .titulo {
  color: #E8E4DC;
}
.toast[data-tipo="Sucesso"][data-faixa="Escura"] .mensagem {
  color: #C9CFE2;
}
.toast[data-tipo="Sucesso"][data-faixa="Escura"] .fechar {
  color: #82ADC3;
}
